<script setup lang="ts">
import { useAuthStore } from '@/stores/auth'
import SafeAnswer from '@/components/SafeAnswer.vue'
import { onMounted, ref } from 'vue'
import { foundation, openDocument, type Asset } from '@/api/foundation'
import { learningApi } from '@/api/learning'
import { messageOf } from '@/api/client'
import type { KnowledgePoint, Document } from '@/api/types'
const auth=useAuthStore()
const assets=ref<Asset[]>([]),points=ref<KnowledgePoint[]>([]),documents=ref<Document[]>([]),error=ref(''),notice=ref(''),busy=ref(false)
function blank():Asset{return {IsPublic:true,ID:'',Kind:'question',PointID:'',Title:'',Status:'unavailable',Revision:0,Payload:{EstimatedMinutes:0,Stem:'',Options:['','','',''],Answer:-1,Explanation:'',Source:'',URL:'',DocumentID:'',Page:0,StartSeconds:0,EndSeconds:0,Difficulty:1}}}
const draft=ref<Asset>(blank()),editing=ref(false)
async function load(){try{assets.value=await foundation.assets();points.value=await learningApi.points();const bases=await learningApi.bases();documents.value=(await Promise.all(bases.map(b=>learningApi.documents(b.ID)))).flat()}catch(e){error.value=messageOf(e)}}
function edit(a?:Asset){draft.value=a?JSON.parse(JSON.stringify(a)):blank();editing.value=true;notice.value='';error.value=''}
async function action(fn:()=>Promise<unknown>){busy.value=true;error.value='';notice.value='';try{await fn();await load()}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
async function save(){await action(async()=>{draft.value=await foundation.saveAsset(draft.value);editing.value=false;notice.value=draft.value.Status==='ready'?'已保存，可直接用于学习。':'已保存，但内容不完整，暂不用于测评或推荐。'})}
async function remove(a:Asset){if(confirm('删除此资源？既有测评仍保留当时的题目快照。'))await action(()=>foundation.removeAsset(a.ID))}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await action(async()=>{if(file.size>1024*1024)throw new Error('导入文件应小于1MB（File too large）');const parsed=JSON.parse(await file.text());const rows=Array.isArray(parsed)?parsed:[parsed];if(rows.length>100)throw new Error('每次最多导入100项（Too many resources）');let count=0;for(const row of rows){try{await foundation.saveAsset({...blank(),...row,ID:'',Revision:0,Status:'unavailable',Payload:{...blank().Payload,...row.Payload}});count++}catch(e){throw new Error(`已导入${count}项；第${count+1}项失败：${messageOf(e)}`)}}notice.value=`已导入${count}项资源，系统已检查完整性。`});(event.target as HTMLInputElement).value='';await load()}
function template(){const b=new Blob([JSON.stringify(blank(),null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='resource-template.json';a.click();URL.revokeObjectURL(url)}
onMounted(load)
</script>
<template><div><header class="page-head"><div><h1>公共与个人学习资源</h1><p>公共课程无需上传即可学习，公共内容仅管理员可以维护。</p></div><button v-if="auth.user?.role==='admin'" class="primary" :disabled="busy" @click="edit()">新建资源</button></header>
<div v-if="error" class="notice error" role="alert">{{error}}</div><div v-if="notice" class="notice" role="status">{{notice}}</div>
<section v-if="auth.user?.role==='admin'" class="card"><div class="toolbar-actions"><button class="secondary" @click="template">下载空白 JSON 模板</button><label>导入资源 JSON <input type="file" accept=".json" :disabled="busy" @change="importFile" /></label></div><p class="muted">PointID 需填写已有知识点 ID，Answer 使用从 0 开始的选项序号；答案未知时填写 -1，可在作答后获取 AI 参考判断。</p></section>
<form v-if="editing" class="card section" @submit.prevent="save"><h2>{{draft.ID?'编辑资源':'新建资源'}}</h2><div class="grid two-col">
<label class="field">资源类型<select v-model="draft.Kind"><option value="question">单选题</option><option value="video">视频</option><option value="material">教材/资料</option></select></label>
<label class="field">知识点<select v-model="draft.PointID" required><option value="" disabled>选择知识点</option><option v-for="p in points" :key="p.ID" :value="p.ID">{{p.SubjectName}} · {{p.Name}}</option></select><small>{{draft.PointID}}</small></label>
<label v-if="auth.user?.role==='admin' && !draft.ID" class="field"><input type="checkbox" v-model="draft.IsPublic" /> 系统公共资源</label><label class="field">标题<input v-model="draft.Title" required maxlength="200" /></label><label class="field">难度（1–5）<input v-model.number="draft.Payload.Difficulty" type="number" min="1" max="5" /></label>
<label class="field">预计学习分钟数（0使用系统估计）<input v-model.number="draft.Payload.EstimatedMinutes" type="number" min="0" max="600" /></label><label class="field">来源说明<input v-model="draft.Payload.Source" placeholder="书名、版本、章节、年份和题号" /></label>
</div>
<template v-if="draft.Kind==='question'"><label class="field">题干<textarea v-model="draft.Payload.Stem" rows="4" /></label><label v-for="(_,i) in draft.Payload.Options" :key="i" class="field">选项 {{String.fromCharCode(65+i)}}<input v-model="draft.Payload.Options[i]" /></label><label class="field">正确答案<select v-model.number="draft.Payload.Answer"><option :value="-1">无资料答案（AI 辅助）</option><option v-for="(_,i) in draft.Payload.Options" :key="i" :value="i">{{String.fromCharCode(65+i)}}</option></select></label><label class="field">答案解析<textarea v-model="draft.Payload.Explanation" rows="4" /></label></template>
<template v-else><template v-if="draft.Kind==='material'"><label class="field">讲解<textarea v-model="draft.Payload.Stem" rows="6" /></label><label class="field">例题与解析<textarea v-model="draft.Payload.Explanation" rows="4" /></label></template><label class="field">资源链接<input v-model="draft.Payload.URL" type="url" placeholder="https://" /></label><template v-if="draft.Kind==='video'"><div class="grid two-col"><label class="field">起始秒<input v-model.number="draft.Payload.StartSeconds" type="number" min="0" /></label><label class="field">结束秒（0表示未指定）<input v-model.number="draft.Payload.EndSeconds" type="number" min="0" /></label></div></template><template v-else><label class="field">关联上传文档<select v-model="draft.Payload.DocumentID"><option value="">不关联</option><option v-for="d in documents" :key="d.ID" :value="d.ID">{{d.OriginalFilename}}</option></select></label><label class="field">PDF页序号（0表示未指定）<input v-model.number="draft.Payload.Page" type="number" min="0" /></label></template></template>
<button class="primary" :disabled="busy">保存资源</button> <button type="button" class="secondary" :disabled="busy" @click="editing=false">取消</button></form>
<section class="card section"><div v-if="!assets.length" class="empty">暂无资源。真实教材、试题及视频尚未导入。</div><div v-else class="list"><article v-for="a in assets" :key="a.ID" class="list-item"><div class="grow"><b>{{a.Title}}</b> <span class="pill">{{a.IsPublic?'系统公共':'个人'}}</span><SafeAnswer v-if="a.Kind==='material' && a.Payload.Stem" :text="a.Payload.Stem+'\n\n'+a.Payload.Explanation" :citations="0"/><p class="reason">{{a.Kind==='question'?'单选题':a.Kind==='video'?'视频':'教材'}} · {{a.Status==='ready'?'可用':'暂不可用'}} · 版本 {{a.Revision}}</p><p>{{a.Payload.Source||'个人提供的资源'}}</p><p v-if="a.Payload.Issue" class="notice error">{{a.Payload.Issue}}</p><p v-if="a.Kind==='question'">{{a.Payload.AnswerOrigin==='source'?'依据资料或个人提供的答案判分':'无资料答案：AI辅助判断默认不计入学情'}}</p><button v-if="a.Payload.DocumentID" class="secondary" @click="action(()=>openDocument(a.Payload.DocumentID,a.Payload.Page))">查看原文</button></div><button v-if="!a.IsPublic || auth.user?.role==='admin'" class="secondary" :disabled="busy" @click="edit(a)">编辑</button><button v-if="!a.IsPublic || auth.user?.role==='admin'" class="secondary" :disabled="busy" @click="remove(a)">删除</button></article></div></section></div></template>
